package com.orderflow.notification.security;import com.orderflow.platform.error.ErrorCode;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.http.HttpStatus;import org.springframework.security.core.AuthenticationException;import org.springframework.security.web.AuthenticationEntryPoint;import org.springframework.stereotype.Component;@Component public class RestAuthenticationEntryPoint implements AuthenticationEntryPoint{private final ApiSecurityErrorWriter w;public RestAuthenticationEntryPoint(ApiSecurityErrorWriter w){this.w=w;}public void commence(HttpServletRequest q,HttpServletResponse p,AuthenticationException e)throws IOException{boolean b=q.getHeader("Authorization")!=null;w.write(q,p,HttpStatus.UNAUTHORIZED,b?ErrorCode.INVALID_TOKEN:ErrorCode.AUTHENTICATION_REQUIRED,b?"The access token is invalid.":"Authentication is required.");}}
